  'privacy.cookies.body': 'Мы используем основные cookies и локальное хранилище для поддержания вашей сессии, запоминания ваших предпочтений (тема, язык) и обеспечения плавного опыта. Мы не используем cookies для отслеживания от третьих лиц.',
  'privacy.thirdParties.title': 'Сервисы третьих лиц',
  'privacy.thirdParties.body': 'Мы можем использовать услуги третьих лиц для специфических функций, таких как ИИ (Anthropic Claude) и push-уведомления. Эти услуги следуют своим собственным политикам конфиденциальности и обрабатывают только минимально необходимые данные.',
  'privacy.rights.title': 'Ваши права',
  'privacy.rights.body': 'Вы имеете право на доступ, исправление, экспорт или удаление ваших личных данных в любое время. Вы можете управлять своими данными в Настройках или связавшись с нашей поддержкой.',
  'privacy.contact.title': 'Свяжитесь с нами',
  'privacy.contact.body': 'По вопросам конфиденциальности или запросам данных свяжитесь по адресу privacy@chatyy.app. Мы ответим в течение 30 дней.',

  // Terms modal
  'terms.title': 'Условия обслуживания',
  'terms.subtitle': 'Руководство по использованию Chatyy',
  'terms.lastUpdated': 'Последнее обновление: Март 2026',
  'terms.acceptance.title': 'Принятие условий',
  'terms.acceptance.body': 'Получая доступ или используя Chatyy, вы соглашаетесь с этими Условиями обслуживания. Если вы не согласны с какой-либо частью этих условий, не используйте сервис.',
  'terms.services.title': 'Описание услуг',
  'terms.services.body': 'Chatyy предоставляет услуги коммуникации по email, включая отправку, получение и управление email, а также функции ИИ, интеграцию с календарем и видеоконференции.',
  'terms.accounts.title': 'Учетные записи пользователей',
  'terms.accounts.body': 'Вы несете ответственность за безопасность своих учетных данных. Не делитесь своим паролем и не допускайте несанкционированного доступа к своей учетной записи. Вам должно быть не менее 13 лет, чтобы использовать этот сервис.',
  'terms.conduct.title': 'Допустимое использование',
  'terms.conduct.body': 'Вы соглашаетесь не использовать сервис для отправки спама, вредоносного ПО, фишинга или любого незаконного контента. Не пытайтесь получить доступ к учетным записям других пользователей или нарушить инфраструктуру сервиса.',
  'terms.content.title': 'Право собственности на контент',
  'terms.content.body': 'Вы сохраняете право собственности на весь контент, который создаете и отправляете через сервис. Мы не претендуем на право собственности на ваши emails или вложения. Мы можем обрабатывать контент по мере необходимости для предоставления сервиса.',
  'terms.limitation.title': 'Ограничение ответственности',
  'terms.limitation.body': 'Chatyy предоставляется "как есть". Мы стремимся к 99,9% доступности, но не гарантируем непрерывную работу. Мы не несем ответственности за косвенные, случайные или последующие убытки, возникающие в результате использования сервиса.',
  'terms.termination.title': 'Закрытие аккаунта',
  'terms.termination.body': 'Мы можем приостановить или закрыть аккаунты, которые нарушают эти условия. Ты можешь удалить свой аккаунт в любое время в Настройках. После закрытия твои данные будут удалены в течение 30 дней.',
  'terms.changes.title': 'Изменения в условиях',
  'terms.changes.body': 'Мы можем периодически обновлять эти условия. Мы уведомим о значительных изменениях по электронной почте или уведомлением в приложении. Продолжение использования после изменений означает принятие обновленных условий.',

