  "backup.protectionTitle": "Как защищена ваша резервная копия",
  "backup.protectionDesc": "Ваши резервные копии хранятся в облаке Chatyy, привязаны к вашему аккаунту и доступны только после входа в него. Передача данных между устройством и нашими серверами идёт по зашифрованному соединению (TLS). Эти копии не защищены сквозным шифрованием.",
