  "liveDiag.clearBody": "Удаляет все журналы публикации эфира. Используй после обращения в поддержку.",
  "liveDiag.whatTitle": "Что это?",
  "liveDiag.whatBody": "Когда ты начинаешь эфир, приложение передает камеру и микрофон на сервер трансляции, который доставляет видео зрителям. Если что-то идет не так (сеть, разрешения, NAT), у зрителей бесконечно висит «Подключение…». Здесь хранятся журналы последней попытки, чтобы ты (или поддержка) мог точно увидеть, где все остановилось.",
